import AppKit
import XCTest

@testable import Workroom

/// D14 / T15: every rail role's contrast floor, measured against **every bundled ghostty theme** rather
/// than a hand-picked pair.
///
/// Two fixtures can't answer this. The rail's colours are derived from a *user-supplied* theme — the tile
/// hues, the accent, the two diff foregrounds and the dimmed subtitle are all computed from whatever
/// `background`/`foreground`/ANSI palette a theme file happens to carry — and the ways that goes wrong are
/// specific to real palettes: a near-monochrome theme, a theme whose ANSI blue is nearly its background, a
/// light theme with a pale accent. The 56 bundled themes ARE the product's input set, so they are what the
/// floors get asserted against.
///
/// The sweep is also what caught the contrast metric itself: `ThemeTokens.luminance` was weighting
/// gamma-encoded sRGB, so 43 of the 56 themes scored below the body-text floor and 38 of them lost the
/// Liquid Glass surface to the opaque fallback. A floor that holds for two fixtures says nothing about the
/// fiftieth theme.
@MainActor
final class SwitcherThemeSweepTests: XCTestCase {

  /// Every bundled theme, parsed. Read from the app bundle's own `ghostty/themes` — deliberately NOT
  /// through `ThemeService.themeDirectories()`, whose first entry is `~/.config/ghostty/themes`: a user
  /// override there would make this test's result depend on the machine running it.
  private func bundledThemes() throws -> [ThemePreview] {
    let root = try XCTUnwrap(
      Bundle.main.resourceURL?.appendingPathComponent("ghostty/themes"),
      "the app bundle must carry its themes — the terminal can't start without them")
    let names = try FileManager.default.contentsOfDirectory(atPath: root.path).sorted()
    let themes = names.compactMap {
      ThemeService.parseThemeFile(atPath: root.path + "/" + $0, name: $0)
    }
    XCTAssertGreaterThan(
      themes.count, 40, "the bundled set is ~56 themes; a near-empty sweep is a bug")
    return themes
  }

  /// Text roles. The guarantee is *two-tiered* by design (D14): a card keeps its Liquid Glass while its
  /// text clears `opaqueFillFloor`, and drops to an opaque fill below that. So the invariant asserted here
  /// is the floor, not the 4.5:1 target — a theme landing in the 4.0–4.5 band deliberately keeps the
  /// material, because going opaque wouldn't raise the ratio anyway (it's measured against `nsPanel`
  /// either way; what it buys is certainty, and that isn't worth the whole surface for a near miss).
  ///
  /// The counts are asserted too, loosely. They are what makes this a regression net rather than a
  /// tautology: if a future change pushes half the bundled set into the near-miss band or into the opaque
  /// fallback, every per-theme assertion above still passes while the rail quietly stops being glass.
  func testEveryBundledThemeKeepsTheRailsTextLegible() throws {
    var fellBack: [String] = []
    var nearMiss: [String] = []
    let themes = try bundledThemes()
    for theme in themes {
      let tokens = ThemeTokens(preview: theme)
      let palette = SwitcherRailLayout.palette(for: tokens)
      if palette.needsOpaqueFill {
        fellBack.append(theme.name)
        continue
      }
      for (role, color) in [("name", palette.nsName), ("subtitle", palette.nsSubtitle)] {
        XCTAssertGreaterThanOrEqual(
          ThemeTokens.contrastRatio(color, tokens.nsPanel),
          SwitcherRailLayout.Palette.opaqueFillFloor - 0.01,
          "\(theme.name): the \(role) is below the floor that keeps the material on")
      }
      if ThemeTokens.contrastRatio(palette.nsName, tokens.nsPanel)
        < SwitcherRailLayout.Palette.textTarget
      {
        nearMiss.append(theme.name)
      }
    }
    // Measured at the time of writing: 1 fallback (iTerm2 Solarized Light, 3.90:1) and 3 in the band
    // (Everforest Light Med 4.39, TokyoNight Day 4.25, iTerm2 Solarized Dark 4.35).
    XCTAssertLessThanOrEqual(
      fellBack.count, 4,
      "the opaque fallback is the exception, not the rule — fell back: \(fellBack)")
    XCTAssertLessThanOrEqual(
      nearMiss.count, 6, "the 4.0–4.5 band should stay a handful — in it: \(nearMiss)")
  }

  /// Indicator roles: 3:1 for the ring, the running dot and the diff bars.
  func testEveryBundledThemeKeepsTheRailsIndicatorsVisible() throws {
    for theme in try bundledThemes() {
      let tokens = ThemeTokens(preview: theme)
      let palette = SwitcherRailLayout.palette(for: tokens)
      for (role, color) in [
        ("ring", palette.nsRing), ("dot", palette.nsDot), ("diffAdd", palette.nsDiffAdd),
        ("diffRemove", palette.nsDiffRemove),
      ] {
        XCTAssertGreaterThanOrEqual(
          ThemeTokens.contrastRatio(color, tokens.nsPanel),
          SwitcherRailLayout.Palette.indicatorTarget - 0.01,
          "\(theme.name): \(role) is below the indicator floor")
      }
    }
  }

  /// Every mark tile, on every theme: the tile must be visible against the card, and its monogram legible
  /// on the tile. The second half is what a brightness-threshold ink rule failed — it took white on a
  /// 0.54-brightness tile at 1.77:1 where black gives 11.8:1 — so `ink` measures both candidates.
  func testEveryBundledThemeKeepsEveryMonogramLegible() throws {
    for theme in try bundledThemes() {
      let tokens = ThemeTokens(preview: theme)
      for hue in 0..<SwitcherMark.hueCount {
        let tile = SwitcherMark.tileColor(hue: hue, tokens: tokens)
        XCTAssertGreaterThanOrEqual(
          ThemeTokens.contrastRatio(tile, tokens.nsPanel), SwitcherMark.tileContrastFloor - 0.01,
          "\(theme.name) hue \(hue): the tile itself disappears into the card")
        XCTAssertGreaterThanOrEqual(
          ThemeTokens.contrastRatio(SwitcherMark.ink(on: tile), tile),
          SwitcherRailLayout.Palette.textTarget - 0.01,
          "\(theme.name) hue \(hue): the monogram is illegible on its own tile")
      }
    }
  }

  /// The badge's own pill: its label against the fill it sits on, and the fill against the card.
  ///
  /// This is the role D14 lists last and the one the rail nearly shipped wrong: `UnreadBadge`'s own colours
  /// are the RAW `accent` with ink on top, and the raw accent is exactly what the ring gets corrected away
  /// from — so a pale-accent theme drew an invisible pill beside a visible ring. The rail passes its own
  /// pair instead, which is `nsRing` plus measured ink.
  func testEveryBundledThemeKeepsTheBadgeReadable() throws {
    for theme in try bundledThemes() {
      let tokens = ThemeTokens(preview: theme)
      let palette = SwitcherRailLayout.palette(for: tokens)
      XCTAssertGreaterThanOrEqual(
        ThemeTokens.contrastRatio(palette.nsBadgeInk, palette.nsBadgeFill),
        SwitcherRailLayout.Palette.textTarget - 0.01,
        "\(theme.name): the unread count is illegible on its own pill")
      XCTAssertGreaterThanOrEqual(
        ThemeTokens.contrastRatio(palette.nsBadgeFill, tokens.nsPanel),
        SwitcherRailLayout.Palette.indicatorTarget - 0.01,
        "\(theme.name): the pill disappears into the card")
    }
  }

  /// The rail's badge and its cursor ring must be the SAME accent. Flagged as an open judgment call when
  /// the rail landed: `legible` walked the ring away from a pale accent while the badge kept the raw one,
  /// so on those themes the two disagreed about what the app's accent is.
  func testTheBadgeAndTheCursorRingAgreeOnTheAccent() throws {
    for theme in try bundledThemes() {
      let palette = SwitcherRailLayout.palette(for: ThemeTokens(preview: theme))
      XCTAssertEqual(
        palette.nsBadgeFill, palette.nsRing,
        "\(theme.name): the badge pill and the cursor ring are both 'the accent'")
    }
  }
}

  ///
  /// The cursor ring clearing 3:1 says nothing about the rest, and the rail's surface is
  /// vibrancy + `panel.opacity(0.7)` over a *user-supplied* ghostty theme — a theme whose foreground
  /// sits close to its background washes out the name, the subtitle and the diff bars while the ring
  /// still passes. So each role gets its own floor: 4.5:1 for text (11–13pt body), 3:1 for indicators,
  /// the ring and the drawn miniatures.
  ///
  /// Resolved as **`NSColor`**, with `Color` accessors on top. Never the other way round: converting a
  /// SwiftUI `Color` back with `NSColor(_:)` yields a lazily-resolved, SwiftUI-backed colour whose
  /// `usingColorSpace` returns nil outside a view update — so a contrast check silently no-ops and
  /// re-wrapping the result in a `Color` crashes in `Color._apply` during layout. Every input here
  /// starts from a `ns*` token.
  struct Palette {
    let nsName: NSColor
    let nsSubtitle: NSColor
    let nsRing: NSColor
    let nsDot: NSColor
    let nsDiffAdd: NSColor
    let nsDiffRemove: NSColor
    /// The unread pill, and the count drawn on it. The rail can't use the shared `UnreadBadge`'s own
    /// colours: those are the raw `accent` with `accentForeground` on top, and `accentForeground` comes
    /// from `ThemeTokens.contrastingForeground`, which flips ink at luminance 0.6 — the same threshold
    /// that left a mark's monogram at 1.77:1 on a 0.54-luminance tile. `nsBadgeFill` is deliberately the
    /// SAME colour as `nsRing`: both are "the accent", and on a pale-accent theme the ring gets corrected
    /// while a raw-accent badge would not, leaving two elements on one card disagreeing about it.
    let nsBadgeFill: NSColor
    let nsBadgeInk: NSColor
    /// True when a floor could not be met by nudging alone, so the card drops vibrancy for an opaque
    /// fill. Legibility outranks the material.
    let needsOpaqueFill: Bool

    var name: Color { Color(nsColor: nsName) }
    var subtitle: Color { Color(nsColor: nsSubtitle) }
    var ring: Color { Color(nsColor: nsRing) }
    var dot: Color { Color(nsColor: nsDot) }
    var diffAdd: Color { Color(nsColor: nsDiffAdd) }
    var diffRemove: Color { Color(nsColor: nsDiffRemove) }
    var badgeFill: Color { Color(nsColor: nsBadgeFill) }
    var badgeInk: Color { Color(nsColor: nsBadgeInk) }

    static let textTarget: CGFloat = 4.5
    static let indicatorTarget: CGFloat = 3.0

    /// When to abandon the material, which is **lower** than `textTarget` on purpose.
    ///
    /// Dropping vibrancy doesn't raise the contrast ratio — it's computed against `nsPanel` either way.
    /// What it buys is *certainty*: an opaque card makes the measured background the real one instead of
    /// whatever the glass happened to sample. That's worth having when text is genuinely hard to read,
    /// and not worth the whole Liquid Glass surface when a theme misses the floor by a hair. Measured
    /// case: a mid-grey card caps white text at 4.45:1 — 99% of the floor, no perceptible difference —
    /// and keying the fallback on `textTarget` turned the glass off for it.
    static let opaqueFillFloor: CGFloat = 4.0
  }

  static func palette(for tokens: ThemeTokens) -> Palette {
    let base = tokens.nsPanel
    let fg = tokens.nsFg
    func fix(_ color: NSColor, _ target: CGFloat) -> NSColor {
      ThemeTokens.legible(color, on: base, towards: fg, target: target)
    }
    let name = fix(fg, Palette.textTarget)
    // `fgDim` is fg at 40% — flattened against the card fill first, because `legible` reasons about
    // opaque colours and a translucent one would measure as its own alpha-less form.
    let dim = base.blended(withFraction: 0.55, of: fg) ?? fg
    let accent = fix(tokens.nsAccent, Palette.indicatorTarget)
    return Palette(
      nsName: name,
      nsSubtitle: fix(dim, Palette.textTarget),
      nsRing: accent,
      nsDot: accent,
      nsDiffAdd: fix(tokens.nsDiffAddFg, Palette.indicatorTarget),
      nsDiffRemove: fix(tokens.nsDiffRemoveFg, Palette.indicatorTarget),
      nsBadgeFill: accent,
      // Whichever of black/white actually wins on this fill, measured — not chosen by a luminance
      // threshold. Shared with the mark's monogram, which is where the measurement came from.
      nsBadgeInk: SwitcherMark.ink(on: accent),
      // `legible` walks towards the foreground and stops at 100%; if even the pure foreground can't come
      // close to the text floor against this fill, the fill itself is the problem.
      needsOpaqueFill: ThemeTokens.contrastRatio(name, base) < Palette.opaqueFillFloor
    )
  }
}

/// Black or white on a fill — whichever actually measures better against it.
///
/// Chosen by measurement rather than by a brightness threshold, which is what this used to do
/// (`luminance > 0.6 ? .black : .white`) and which fails in a whole band: a tile at 0.54 apparent
/// brightness took white at 1.77:1 where black gives 11.8:1 — a real, illegible monogram, found on a
/// dark-theme fixture. Comparing both ratios has no threshold to get wrong.
static func contrastingForeground(for color: NSColor) -> NSColor {
  contrastRatio(.black, color) >= contrastRatio(.white, color) ? .black : .white
}

// MARK: Syntax highlighting

/// The colour for a tree-sitter highlight capture, or `nil` (⇒ render in the default foreground).
/// `onAddedBackground` applies the contrast guard against the green add tint so token colours
/// don't wash out on added lines; context lines (≈ theme background) use the base colour.
func syntaxColor(forCapture capture: String, onAddedBackground: Bool = false) -> Color? {
  guard let category = Self.category(for: capture), let base = syntaxByCategory[category] else {
    return nil
  }
  guard onAddedBackground else { return Color(nsColor: base) }
  return Color(nsColor: Self.legible(base, on: nsAddBackgroundOpaque, towards: nsFg))
}

/// Collapse any tree-sitter capture name (e.g. `function.method.builtin`, `string.special.path`)
/// to a colour category by its leading dotted component. Unknown captures return `nil` (default
/// foreground). This is the whole capture→colour vocabulary — grammar-specific leaf captures fold
/// into their family.
static func category(for capture: String) -> SyntaxCategory? {
  let head = capture.split(separator: ".").first.map(String.init) ?? capture
  switch head {
  case "keyword", "conditional", "repeat", "include", "exception", "define", "storageclass",
    "modifier", "operator":
    // `operator` reads as a keyword-ish accent rather than dim punctuation.
    return head == "operator" ? .punctuation : .keyword
  case "function", "method", "constructor", "call":
    return .function
  case "type", "class", "interface", "enum", "struct":
    return .type
  case "namespace", "module", "package":
    return .namespace
  case "constant", "boolean", "const":
    return .constant
  case "number", "float", "integer":
    return .number
  case "string", "char", "character":
    return .string
  case "comment":
    return .comment
  case "variable", "parameter", "identifier":
    return .variable
  case "property", "field", "member":
    return .property
  case "tag":
    return .tag
  case "attribute", "annotation", "decorator":
    return .attribute
  case "punctuation", "delimiter", "bracket":
    return .punctuation
  case "escape", "regex", "embedded":
    return .escape
  default:
    return nil
  }
}

/// Nudge `color` toward `fg` until it has at least a 3:1 WCAG contrast ratio against `bg`, so a
/// token colour close to the add-tint hue (e.g. a green string on the green add background) stays
/// readable. Capped iterations; returns the best achieved if the target is unreachable.
static func legible(_ color: NSColor, on bg: NSColor, towards fg: NSColor, target: CGFloat = 3.0)
  -> NSColor
{
  guard let srgb = color.usingColorSpace(.sRGB), let fgSrgb = fg.usingColorSpace(.sRGB) else {
    return color
  }
  var current = srgb
  var fraction: CGFloat = 0
  while contrastRatio(current, bg) < target, fraction < 1.0 {
    fraction += 0.2
    current = srgb.blended(withFraction: fraction, of: fgSrgb) ?? srgb
  }
  return current
}

/// WCAG relative-luminance contrast ratio between two colours (1…21).
static func contrastRatio(_ a: NSColor, _ b: NSColor) -> CGFloat {

import AppKit

/// A workroom's identity mark for the ⌥Tab rail (issue #132): a colour and a monogram, both derived,
/// neither stored.
///
/// The point is **recognition before reading**. ⌘Tab works because app icons are stable and distinctive;
/// a screenshot of a terminal is neither — it changes every time and looks like every other terminal.
/// So a workroom gets a mark it keeps for the life of the workroom, and you learn "the teal AR one" the
/// same way you learn an app icon.
struct SwitcherMark: Equatable {
  /// One or two characters. Derived from the **displayed** name, so it matches what you read on the card.
  let monogram: String
  /// Which of `hueCount` hues. Derived from the **stable** name, so a relabel (issue #41) changes the
  /// letters without moving the colour — the thing you actually recognise stays put.
  let hue: Int

  /// Number of distinct hues. **12, not 6.** With six buckets and four open workrooms a collision is
  /// more likely than not — measured live: two of four tiles came out the same colour. Twelve keeps
  /// neighbouring hues clearly apart (30° of the wheel) while making a clash uncommon.
  static let hueCount = 12

  init(displayName: String, stableKey: String) {
    monogram = Self.monogram(for: displayName)
    hue = Self.hue(for: stableKey)
  }

  /// Direct construction, for `disambiguate` reassigning a hue without re-deriving the monogram.
  init(monogram: String, hue: Int) {
    self.monogram = monogram
    self.hue = hue
  }

  /// Two characters that actually *distinguish* the name.
  ///
  /// Tuned for what Workroom generates: `namegen` produces adjective-noun pairs like
  /// `partitioned-crescent`, where initials ("PC") carry far more than the first two letters ("PA").
  ///
  /// But plain initials repeat the mistake D12 fixed for titles. `uitest-room`, `uitest-room-2` and
  /// `uitest-room-3` all reduce to "UR" — four identical tiles, which is worse than no tile at all. So a
  /// **trailing number is always kept**, because when a name ends in one that digit is the whole
  /// difference: "uitest-room-2" → "R2".
  static func monogram(for name: String) -> String {
    let separators = CharacterSet(charactersIn: "-_. /")
    let words = name.components(separatedBy: separators).filter { !$0.isEmpty }
    guard let first = words.first else { return "?" }

    // A trailing number is the distinguishing part — pair it with the initial of the word before it.
    if words.count >= 2, let last = words.last, last.allSatisfy(\.isNumber) {
      let stem = words.count >= 3 ? words[words.count - 2] : first
      return (String(stem.prefix(1)) + String(last.suffix(1))).uppercased()
    }
    if words.count >= 2, let second = words.dropFirst().first(where: { $0.first != nil }) {
      return (String(first.prefix(1)) + String(second.prefix(1))).uppercased()
    }
    return String(first.prefix(2)).uppercased()
  }

  /// The tile colour for a hue bucket.
  ///
  /// Deliberately **not** `ThemeTokens.legible`, which walks a colour toward the foreground until it
  /// clears a contrast floor. That is right for text and wrong here: on a light theme it walked every
  /// insufficiently-contrasty hue to near-black, so every tile collapsed into identical charcoal and the
  /// mark stopped marking anything — observed live before this existed.
  ///
  /// So hue is treated as identity and never adjusted; only saturation and brightness move, until the
  /// tile clears its floor against this theme's panel.
  static func tileColor(hue index: Int, tokens: ThemeTokens) -> NSColor {
    // Anchored on the theme's accent hue and spaced evenly around the wheel from there, so the marks
    // belong to the theme without being limited to the six ANSI slots — and a greyscale accent still
    // yields twelve usable angles.
    let accent = tokens.nsAccent.usingColorSpace(.sRGB)
    let anchor = (accent?.saturationComponent ?? 0) > 0.15 ? (accent?.hueComponent ?? 0) : 0
    let hueAngle = (anchor + CGFloat(index % hueCount) / CGFloat(hueCount)).truncatingRemainder(
      dividingBy: 1)
    let dark = tokens.colorScheme == .dark
    func ratio(_ color: NSColor) -> CGFloat { ThemeTokens.contrastRatio(color, tokens.nsPanel) }
    // Search brightness first, then give saturation ground — hue is identity and never moves.
    //
    // Two things this gets right that a single fixed walk did not, both measured rather than reasoned:
    //
    // 1. **Both directions.** The preferred one comes from `colorScheme`, which is derived from the
    //    theme's *background*, while the tile is measured against its *panel*. On a theme where those sit
    //    on opposite sides of mid-grey, a one-way walk moved the tile TOWARD the panel and nothing ever
    //    cleared 3:1.
    // 2. **Saturation is a fallback axis.** A mid-tone card caps how much contrast a saturated colour can
    //    reach at all: against this app's grey card (luminance 0.186) the *best* a 0.62-saturated hue can
    //    do is 2.71:1 at full brightness, because a saturated colour can't get light enough. Desaturating
    //    buys the luminance that brightness alone cannot — a pale blue clears the floor where a vivid one
    //    can't — and it stays visibly a hue, which a walk toward the foreground (`legible`) would not.
    let ladder: [CGFloat] = dark ? [0.55, 0.46, 0.38, 0.34] : [0.62, 0.52, 0.42, 0.34]
    var best: NSColor?
    for saturation in ladder {
      func tile(_ brightness: CGFloat) -> NSColor {
        NSColor(hue: hueAngle, saturation: saturation, brightness: brightness, alpha: 1)
      }
      let start: CGFloat = dark ? 0.72 : 0.62
      let lighter = Array(stride(from: start, through: 0.98, by: 0.03)).map(tile)
      let darker = Array(stride(from: start, through: 0.10, by: -0.03)).map(tile)
      let ordered = dark ? lighter + darker : darker + lighter
      if let clears = ordered.first(where: { ratio($0) >= Self.tileContrastFloor }) {
        return clears
      }
      if let rung = ordered.max(by: { ratio($0) < ratio($1) }),
        ratio(rung) > ratio(best ?? rung) || best == nil
      {
        best = rung
      }
    }
    // Nothing in the ladder clears the floor against this card — take the best available rather than
    // whatever the last walk happened to stop on. `SwitcherRailLayout.Palette.needsOpaqueFill` is the
    // wider guard for a theme this hostile.
    return best ?? NSColor(hue: hueAngle, saturation: ladder[0], brightness: 0.62, alpha: 1)
  }

  /// The tile's contrast floor against the card. 3:1 — the tile is a large solid shape, not text.
  static let tileContrastFloor: CGFloat = 3.0

  /// The monogram's ink: whichever of black/white actually measures better on this tile.
  ///
  /// This existed as its own implementation because `ThemeTokens.contrastingForeground` used to switch on
  /// a brightness threshold (`> 0.6`), which left a tile at 0.54 taking WHITE at 1.77:1 where black gives
  /// 11.8:1 — an illegible monogram, measured on a dark-theme fixture. That helper now measures both
  /// candidates, exactly as this did, so this is a name for the rail's use of it rather than a second
  /// rule. Kept as the call site the rail reads, and as the record of why the threshold went.
  static func ink(on tile: NSColor) -> NSColor {
    ThemeTokens.contrastingForeground(for: tile)
  }

  /// Rotate hues so that **no two marks on one rail share a colour**.
  ///
  /// A stable per-name hue is right in isolation and not sufficient in practice: with 12 buckets and 4
  /// open workrooms a clash happens ~43% of the time, and it happened in both live checks. Since the
  /// rail's job is telling *these* items apart, uniqueness is enforced over the visible set — a colliding
  /// mark steps to the next free hue. Deterministic for a given ordered list, and a no-op once there are
  /// more items than hues.

