def parse(p):
    bg=fg=None; pal={}
    for raw in open(p,encoding='utf-8',errors='replace'):
        line=raw.strip()
        m=re.match(r'^(background|foreground)\s*=\s*#?([0-9a-fA-F]{6})$',line)
        if m:
            v=int(m.group(2),16); c=((v>>16)/255,((v>>8)&255)/255,(v&255)/255)
            if m.group(1)=='background': bg=c
            else: fg=c
        m=re.match(r'^palette\s*=\s*(\d+)\s*=\s*#?([0-9a-fA-F]{6})$',line)
        if m:
            v=int(m.group(2),16); pal[int(m.group(1))]=((v>>16)/255,((v>>8)&255)/255,(v&255)/255)
    if bg is None or fg is None: return None
    return bg,fg,pal

def lin(x): return x/12.92 if x<=0.03928 else ((x+0.055)/1.055)**2.4
def lum(c): 
    r,g,b=[lin(x) for x in c]; return 0.2126*r+0.7152*g+0.0722*b
def cr(a,b):
    la,lb=lum(a),lum(b); hi,lo=max(la,lb),min(la,lb); return (hi+0.05)/(lo+0.05)
def pbright(c): return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]
def blend(a,b,f): return tuple(a[i]*(1-f)+b[i]*f for i in range(3))
def legible(color,bg,fg,target):
    cur=color; frac=0.0
    while cr(cur,bg)<target and frac<1.0:
        frac+=0.2; cur=blend(color,fg,frac)
    return cur
def ink(t): return (0,0,0) if cr((0,0,0),t)>=cr((1,1,1),t) else (1,1,1)
def hsb(h,s,v): return colorsys.hsv_to_rgb(h,s,v)
def rgb2hsv(c): return colorsys.rgb_to_hsv(*c)

def frange(a,b,step):
    out=[];x=a
    if step>0:
        while x<=b+1e-9: out.append(x); x+=step
    else:
        while x>=b-1e-9: out.append(x); x+=step
    return out

def tile_color(idx,accent,panel,scheme_dark):
    h,s,v=rgb2hsv(accent)
    anchor=h if s>0.15 else 0.0
    hue=(anchor+idx/12.0)%1.0
    ladder=[0.55,0.46,0.38,0.34] if scheme_dark else [0.62,0.52,0.42,0.34]
    best=None
    for sat in ladder:
        start=0.72 if scheme_dark else 0.62
        lighter=[hsb(hue,sat,b) for b in frange(start,0.98,0.03)]
        darker=[hsb(hue,sat,b) for b in frange(start,0.10,-0.03)]
        ordered=(lighter+darker) if scheme_dark else (darker+lighter)
        clears=next((t for t in ordered if cr(t,panel)>=3.0),None)
        if clears: return clears
        rung=max(ordered,key=lambda t:cr(t,panel))
        if best is None or cr(rung,panel)>cr(best,panel): best=rung
    return best or hsb(hue,ladder[0],0.62)

def evaluate(name,d):
    bg,fg,pal=d
    panel=blend(bg,fg,0.055)
    scheme_dark = not (pbright(bg)>0.5)
    def p(i): return pal.get(i)
    accent=p(4) or (0.2,0.4,1.0)
    nameC=legible(fg,panel,fg,4.5)
    crName=cr(nameC,panel)
    fell = crName<4.0
    near = (not fell) and crName<4.5
    fails=[]
    if not fell:
        dim=blend(panel,fg,0.55)
        sub=legible(dim,panel,fg,4.5)
        if cr(sub,panel)<4.0-0.01: fails.append(f"subtitle {cr(sub,panel):.2f}")
    ringC=legible(accent,panel,fg,3.0)
    for role,c in (("ring",ringC),("dot",ringC),
                   ("diffAdd",legible(p(2) or (0,1,0),panel,fg,3.0)),
                   ("diffRemove",legible(p(1) or (1,0,0),panel,fg,3.0))):
        if cr(c,panel)<3.0-0.01: fails.append(f"{role} {cr(c,panel):.2f}")
    bi=ink(ringC)
    if cr(bi,ringC)<4.5-0.01: fails.append(f"badgeInk {cr(bi,ringC):.2f}")
    if cr(ringC,panel)<3.0-0.01: fails.append(f"badgeFill {cr(ringC,panel):.2f}")
    for hue in range(12):
        t=tile_color(hue,accent,panel,scheme_dark)
        if cr(t,panel)<3.0-0.01: fails.append(f"tile{hue} {cr(t,panel):.2f}")
        if cr(ink(t),t)<4.5-0.01: fails.append(f"mono{hue} {cr(ink(t),t):.2f}")
    return crName,fell,near,fails

def sweep(root,names=None):
    res={}
    for n in sorted(os.listdir(root)):
        if names is not None and n not in names: continue
        p=os.path.join(root,n)
        if not os.path.isfile(p) or n in ('LICENSE','SOURCE.md'): continue
        d=parse(p)
        if not d: continue
        res[n]=evaluate(n,d)
    return res

