/// The global ⌘§ show/hide shortcut while enabled, else nil (issue #13). Registered/torn down by
/// `updateGlobalHotkey()` to follow the `globalHotkey` setting.
private var showHideHotkey: GlobalHotkey?
/// The global ⌥§ quick-terminal shortcut while enabled, else nil (issue #39). Registered/torn down
/// alongside `showHideHotkey` by `updateGlobalHotkey()` under the same `globalHotkey` setting.
private var quickTerminalHotkey: GlobalHotkey?
/// The quick terminal (issue #39) — a ~/ shell in its own chrome-less window. One persistent
/// controller; its window/surface come and go as it's summoned/closed.
private let quickTerminal = QuickTerminalController()
/// Retains the `.showQuickTerminal` observer (posted by the toolbar button) for the app's lifetime.
private var quickTerminalObserver: NSObjectProtocol?
/// Observes the `globalHotkey` setting so toggling it takes effect immediately.
private var hotkeyObservation: Task<Void, Never>?
/// The system menu-bar item (issue #33) — an `NSStatusItem` owned here so a click can branch on the
/// notification count (open the list, or just focus the app when there's nothing pending). Retained
/// for the app's lifetime; created in `applicationDidFinishLaunching`.
private var menuBarController: MenuBarController?
/// Catches SIGTERM so a signalled quit stops run commands gracefully (issue #7). Retained so the
/// `DispatchSource` stays alive for the process's lifetime.
private var sigtermSource: DispatchSourceSignal?

deinit { hotkeyObservation?.cancel() }

/// The store a shortcut in the key monitor below may act on: the one owning the window the event is
/// actually headed for, and only while that window has no command-palette dialog up.
///
/// Deliberately **not** `WindowRegistry.keyStore`. That resolves
/// `store(for: NSApp.keyWindow) ?? lastActiveStore ?? allStores.first` (WindowRegistry.swift:113),
/// so it falls back *past* a foreign key window — which is right for its other three callers (the
/// menu-bar popover, where `store(for:)` is legitimately nil; notification-click routing; the
/// terminal context menu) but wrong here: it fires ⌘R / ⌘1-9 / ⌥⌘S into a *background* workroom
/// whenever a sheet, Settings, About, Sparkle's updater or the quick terminal is key. Those windows
/// are all unregistered, so `store(for:)` returns nil for them with no extra checks — which is what
/// lets every branch below simply no-op instead of needing a swallow-with-allowlist (an allowlist
/// was the first design; it was the sole source of a ⌘⌫ gap, broken ⌘V on non-Latin layouts, and a
/// ⌘↑/⌘↓ collision with the Scroll to Top/Bottom menu items).
/// `registry` is injectable purely so tests don't have to mutate the `WindowRegistry.shared`
/// singleton — registering on it leaks window registrations into later tests unless every test pairs
/// its cleanup in tearDown. Production always takes the default.
@MainActor static func shortcutStore(
  for window: NSWindow?, in registry: WindowRegistry = .shared
) -> AppStore? {
  guard let store = registry.store(for: window), store.activePicker == nil else { return nil }
  return store
}

/// What a quick-switcher keystroke (⌥Tab / ⌃Tab, issue #132) should do for `window`.
///
/// Three outcomes, because this shortcut is the first one whose consumption is *conditional*:
/// - `.passThrough` — not one of our windows (Settings, About, the quick terminal). The key belongs
///   to whatever is focused there, so ⌃Tab still reaches a TUI in the quick terminal.
/// - `.swallow` — one of ours with a modal up. Raising a window and moving its selection under its
///   own sheet would leave that sheet acting on a workroom the user never chose (for the commit
///   sheet, a wrong-target VCS write). Gated on the FULL `hasModalPresentation` predicate, not
///   `activePicker` — hence resolving through the registry rather than `shortcutStore`, which nils
///   out a picker window and a foreign window alike, two cases that must differ here.
/// - `.act(store)` — go ahead; whether the event is consumed then depends on whether the switcher
///   actually switched (nothing to switch to ⇒ the terminal keeps the key).
///
/// `registry` is injectable for the same reason as `shortcutStore`'s: so tests don't register windows
/// on the shared singleton.
@MainActor static func switcherGate(
  for window: NSWindow?, in registry: WindowRegistry = .shared
) -> SwitcherGate {
  guard let store = registry.store(for: window) else { return .passThrough }
  return store.hasModalPresentation ? .swallow : .act(store)
}

/// Whether `window` is one of ours *and* has a command-palette dialog open — the case where a
/// shortcut must be actively swallowed rather than merely no-op'd, because the branch doesn't
/// consult a store at all (⌘` window cycling).
@MainActor static func hasModalPicker(
  _ window: NSWindow?, in registry: WindowRegistry = .shared
) -> Bool {
  registry.store(for: window)?.activePicker != nil
}

func applicationDidFinishLaunching(_ notification: Notification) {
  // Disable native macOS window tabbing. It tabs whole app windows (each with its own
  // sidebar) — a level above our per-workroom terminal tabs and a poor fit for a
  // single-window, sidebar-driven app. Off, it also drops the auto-injected
  // "Show/Hide Tab Bar" + "Show All Tabs" View-menu items that otherwise read as if they
  // control the terminal tabs.
  NSWindow.allowsAutomaticWindowTabbing = false

  // Receive notification clicks (authorization is requested lazily on first post).
  UNUserNotificationCenter.current().delegate = self

  // Install the menu-bar item (issue #33). Creating it here also forces `WindowRegistry.shared`
  // into existence early, so its key-window observer is live before the first window appears.
  menuBarController = MenuBarController(registry: .shared)

  // Build the switcher rail's panel now, ordered out, and connect it to the session controller
  // (issue #132). Pre-created on purpose: the first `NSHostingView` render costs real milliseconds,
  // and the 250 ms reveal is the worst possible moment to pay it.
  SwitcherPanelController.shared.prepare()
  SwitcherPanelController.shared.attach(to: .shared)

  monitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
    let flags = event.modifierFlags.intersection([.command, .shift, .option, .control])
    // ⌘W closes the quick terminal (issue #39) when its window is key. The menu's "Close Terminal"
    // ⌘W targets the main window's tabs and would otherwise win, so catch it here (like ⌘R / ⌘1–9
    // above) and route to the quick-terminal window — its delegate (QuickTerminalController) tears
    // the surface down. Gated on the key window being a QuickTerminalWindow, so ⌘W still closes a
    // main-window terminal tab everywhere else.
    if flags == .command, event.charactersIgnoringModifiers == "w",
      let quickTerminalWindow = (event.window ?? NSApp.keyWindow) as? QuickTerminalWindow
    {
      quickTerminalWindow.performClose(nil)
      return nil
    }
    // ⌘W on an auxiliary window (Settings, About) — a window with no AppStore (not a workroom
    // window). The menu's "Close Terminal" owns ⌘W app-wide but is disabled there (no focused
    // terminal), so ⌘W would otherwise just beep. Close the window, as the standard File ▸ Close
    // would. Workroom windows (store != nil) fall through so their "Close Terminal" still fires.
    if flags == .command, event.charactersIgnoringModifiers == "w",
      let keyWindow = event.window ?? NSApp.keyWindow,
      MainActor.assumeIsolated({ WindowRegistry.shared.store(for: keyWindow) }) == nil
    {
      keyWindow.performClose(nil)
      return nil
    }
    // The window this event is headed for, resolved once for every branch below. `event.window` is
    // nil for ⌘ key-equivalents, hence the `?? NSApp.keyWindow` — same idiom as the two ⌘W branches
    // above. Those two run BEFORE this point on purpose: ⌘W acts on the modal in front (a sheet, the
    // quick terminal), not on the window behind it, so it must keep working while a dialog is up.
    let window = event.window ?? NSApp.keyWindow
    // ⌘` / ⇧⌘`: cycle key focus through the app's windows incl. the quick terminal (issue #87) —
    // the standard "Move focus to next window" shortcut. Caught here, like ⌘1–9, so the focused
    // terminal surface doesn't swallow the backtick as input. keyCode 50 is the grave (`) key,

import AppKit
import SwiftUI

/// Extends the active theme into the window's title bar (issue #36). The toolbar's own material is
/// hidden (`.toolbarBackground(.hidden)` in `RootView`) and the title bar is made transparent, so
/// the window's background colour — set here to the active theme background — shows through the top
/// strip. This is the canonical themed-terminal-app look: the title bar matches the terminal and
/// chrome instead of staying system grey/white. Re-applies on `.themeDidChange` so a theme switch
/// repaints the title bar live.
///
/// A zero-size probe view locates the host `NSWindow` once it's mounted.
struct WindowBackgroundThemer: NSViewRepresentable {
  func makeNSView(context: Context) -> NSView {
    let probe = NSView(frame: .zero)
    DispatchQueue.main.async { [weak probe] in Self.apply(to: probe?.window) }
    context.coordinator.observer = NotificationCenter.default.addObserver(
      forName: .themeDidChange, object: nil, queue: .main
    ) { [weak probe] _ in
      MainActor.assumeIsolated { Self.apply(to: probe?.window) }
    }
    return probe
  }

  func updateNSView(_ nsView: NSView, context: Context) {
    Self.apply(to: nsView.window)
  }

  func makeCoordinator() -> Coordinator { Coordinator() }

  final class Coordinator {
    var observer: NSObjectProtocol?
    deinit {
      if let observer { NotificationCenter.default.removeObserver(observer) }
    }
  }

  @MainActor private static func apply(to window: NSWindow?) {
    guard let window else { return }
    // Content extends up under the (transparent) title bar so the custom bar can be drawn as the
    // top strip of the content at any height — see `WorkroomTitlebar` / `TitlebarBars`.
    window.styleMask.insert(.fullSizeContentView)
    window.titlebarAppearsTransparent = true
    // No title text in the bar — the leading/trailing title-bar accessories (the unified toolbar) and
    // the workroom tabs carry the chrome; an app-name title would just clutter the row. Set here (not
    // via SwiftUI `.toolbar(removing: .title)`) because SwiftUI no longer manages this window's
    // toolbar — see the empty AppKit toolbar below. `.navigationTitle` still re-asserts a visible title
    // on some updates, so `AppStore.attachWindow`'s `didUpdate` re-hide lock backstops this.
    window.titleVisibility = .hidden
    // Kill the window toolbar. The taller single-row title bar (with the traffic lights centered in
    // it — the breathing room, issue #23) comes from the full-width `.left` titlebar accessory
    // (`TitlebarAccessoryHost`), which grows the titlebar to its own height; the toolbar is NOT needed
    // for that. We must remove it because `NavigationSplitView` (in RootView) auto-injects a
    // sidebar-toggle toolbar item even with the sidebar column forced `.detailOnly`, and that single
    // item is poison two ways: (a) it renders as a stray `»` "more toolbar items" overflow popup in
    // the title bar, and (b) it keeps SwiftUI's `AppKitToolbarItem.updateMenuFormRepresentation` alive
    // — recomputed on every layout pass, it bridges an NSAttributedString attributes dict into
    // `swift_dynamicCast` → `_dyld_find_foreign_type_protocol_conformance` (a linear scan of every
    // loaded Mach-O image; this app links many: GhosttyKit, the Rust VCS xcframework, SwiftGitX/
    // libgit2, Sparkle), stacking up to the ≥2s macOS-26 AppHangs. SwiftUI OWNS this toolbar and
    // re-injects the toggle, so `.toolbar(removing: .sidebarToggle)` is a no-op — we strip it in AppKit
    // instead, on every apply, and hide the bar so the `»` never shows. Our own sidebar toggle lives in
    // the `.left` accessory (`LeadingTitlebarBar`).
    window.toolbar?.isVisible = false
    // `.none` separator so no hairline rule appears under the bar when the terminal scrolls.
    window.titlebarSeparatorStyle = .none
    // The title bar belongs to the chrome panel, so it takes the panel colour (a subtle step off
    // the terminal background) — title bar + tab bar + panel read as one surface, terminals as
    // another (issue #36).
    window.backgroundColor = ThemeService.shared.tokens.nsPanel
    // We no longer hand-position the traffic lights. Manually moving the standard window
    // buttons into our 38pt bar fought AppKit (it re-lays them to the standard row on every layout
    // change — opening the first terminal, resize, fullscreen — so they shifted, and re-centering on
    // every update jittered). The lights now sit at AppKit's natural position, stable. `RootView`'s
    // bar content is inset to clear them (`WorkroomTitlebar.trafficLightInset`).
  }
}

  tokens = ThemeTokens(preview: Self.themePreview(named: Self.activeThemeName(isDark: isDark)))
}

// MARK: Resolution (static — also called by GhosttyApp.writeThemeConfig without the instance)

nonisolated static func family(named name: String) -> ThemeFamily? {
  families.first { $0.name == name }
}

/// The active variant file name for an appearance: the selected family's variant for that mode,
/// else the Workroom default. Always sanitised (safe to write into the conf).
nonisolated static func activeThemeName(isDark: Bool) -> String {
  let resolved =
    family(named: Defaults[.themeFamily])?.variant(isDark: isDark)
    ?? family(named: defaultFamilyName)!.variant(isDark: isDark)
  return sanitizedThemeName(resolved)
}

/// Strip anything that would break or inject into the generated `ghostty.conf` (the name is
/// written as `theme = "<name>"`), and reject path separators so a crafted `~/.config` filename
/// can't escape the themes dir.
nonisolated static func sanitizedThemeName(_ name: String) -> String {
  name.filter { $0 != "\"" && $0 != "\n" && $0 != "\r" && $0 != "/" && $0 != "\\" }
}

// MARK: The chokepoint

/// THE single apply path. Every trigger (picker selection, appearance change, first run) routes
/// here. Steps: (1) validate the active name resolves — reset to Workroom if not, so terminal
/// *and* chrome fall back to the *same* theme; (2) recompute chrome tokens; (3) re-theme live
/// terminals (regenerates the conf with the new `theme=` and force-reloads); (4) notify AppKit
/// sites that read `ThemeService.shared.tokens` outside SwiftUI.
func applyActiveTheme(force: Bool = true) {
  validateSelection()
  let isDark = Self.isCurrentAppearanceDark()
  tokens = ThemeTokens(preview: Self.themePreview(named: Self.activeThemeName(isDark: isDark)))
  generation &+= 1
  for sessions in terminalSinks.allObjects { sessions.applyThemeToAll(force: force) }
  NotificationCenter.default.post(name: .themeDidChange, object: nil)
}

func applyFamily(_ name: String) {
  Defaults[.themeFamily] = name
  applyActiveTheme()
}

/// If the stored family no longer resolves (e.g. an old key references a renamed family), reset
/// to the Workroom default so the terminal (ghostty) and chrome don't diverge onto different
/// fallbacks.
private func validateSelection() {
  if Self.family(named: Defaults[.themeFamily]) == nil {
    Defaults[.themeFamily] = Self.defaultFamilyName
  }
}

// MARK: Resolution

/// Parsed previews for the **bundled** dir only, keyed by theme name.
///
/// `ThemePicker` calls `themePreview` twice per row *inside the row body* (`ThemePicker.swift`),
/// and every `FamilyRow` observes `ThemeService.shared` for `tokens` — so each ↑/↓, which applies a
/// theme and replaces `tokens`, invalidates every instantiated row and sent all of them back to
/// disk. With 58 families that is up to 116 synchronous file reads per keypress on the main actor,
/// on top of the conf rewrite + engine reload the apply already does.
///
/// Only the bundled dir is cached, and that is what makes the cache correct rather than merely
/// fast: those files cannot change while the app is running, so an entry can never go stale.
/// `~/.config` is re-read on every call (below) precisely so a user editing their own theme still
/// sees it change.
///
/// `nonisolated(unsafe)` + a lock rather than `@MainActor`: `themePreview` is `nonisolated` and
/// `GhosttyApp.writeThemeConfig` resolves off the main actor, so main-actor-isolating the storage
/// would force call-site changes there. The lock keeps the isolation contract unchanged.
private nonisolated(unsafe) static var bundledPreviewCache: [String: ThemePreview] = [:]
private static let bundledPreviewCacheLock = NSLock()

/// Drop the bundled cache. Tests only — a process-lifetime static otherwise leaks state across
/// test cases and makes the "a user override still wins" case impossible to isolate.
nonisolated static func resetPreviewCacheForTesting() {
  bundledPreviewCacheLock.lock()
  bundledPreviewCache.removeAll()
  bundledPreviewCacheLock.unlock()
}

/// Resolve one theme name to its parsed colours, with `~/.config` winning over bundled — the
/// SAME precedence as ghostty's terminal resolution, so chrome and terminal never diverge for a
/// user-overridden theme file.
nonisolated static func themePreview(named name: String) -> ThemePreview? {
  // User dir stays uncached and is checked first, preserving both ghostty's precedence and the
  // ability to edit a theme live.
  if let userDir = themeDirectories().first {
    let path = userDir + "/" + name
    if FileManager.default.fileExists(atPath: path),
      let theme = parseThemeFile(atPath: path, name: name)
    {
      return theme
    }
  }

  bundledPreviewCacheLock.lock()
  defer { bundledPreviewCacheLock.unlock() }
  if let hit = bundledPreviewCache[name] { return hit }
  for dir in themeDirectories().dropFirst() {
    let path = dir + "/" + name
    if FileManager.default.fileExists(atPath: path),
      let theme = parseThemeFile(atPath: path, name: name)
    {
      bundledPreviewCache[name] = theme
      return theme
    }

