func testThePickerIsAMovableWindowOfItsOwn() throws {
  let app = launchedApp()
  openPicker(app)

  let panel = app.windows["Theme"]
  XCTAssertTrue(
    panel.waitForExistence(timeout: 5),
    "the picker is no longer a window of its own — a sheet would not be listed here")

  let before = panel.frame
  // Drag by the title bar, well clear of the close button.
  let titleBar = panel.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.02))
  titleBar.press(
    forDuration: 0.2, thenDragTo: titleBar.withOffset(CGVector(dx: -120, dy: 90)))

  XCTAssertTrue(
    panel.frame.origin != before.origin,
    "the picker did not move — an anchored presentation is exactly the reported bug")
}

