  ///
  /// `setFrameUsingName` is checked rather than trusted: a frame saved on a monitor that is no longer
  /// attached restores off-screen, and a panel the user cannot see is a panel they cannot close.
  private func positionIfNeeded(_ panel: ThemePanel) {
    // Autosave is skipped under the UI-test fixture: the frame lands in `UserDefaults`, which
    // `cfprefsd` resolves against the real home no matter what `$HOME` a test run sets — so a test that
    // drags the panel would otherwise move where it opens for the developer, permanently.
    if !UITestFixture.isActive { panel.setFrameAutosaveName(Self.frameAutosaveName) }
    let screens = NSScreen.screens.map(\.visibleFrame)
