input.old_string:
/// The picker is its own window and it can be dragged — the half of the bug report a unit test can
/// only approach through `NSPanel` properties (`ThemePanelTests`). It used to be a sheet: attached
/// under the workroom window's title bar, with nothing to drag, sitting on top of the content whose
/// colours you were choosing.
///
/// The other half of the report — that the sheet's modality made the app behind it render inactive —
/// is not asserted here: XCUITest exposes no window key/main state and no pixels. It's pinned as
/// `canBecomeMain == false` in `ThemePanelTests`, which is the property that causes it.
func testThePickerIsAMovableWindowOfItsOwn() throws {
  let app = launchedApp()
  openPicker(app)

  let panel = app.windows["Theme"]
  XCTAssertTrue(
    panel.waitForExistence(timeout: 5),
    "the picker is no longer a window of its own — a sheet would not be listed here")

  let before = panel.frame
  // Drag by the title bar, well clear of the close button.
  let titleBar = panel.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.02))
  titleBar.press(
    forDuration: 0.2, thenDragTo: titleBar.withOffset(CGVector(dx: -120, dy: 90)))

  XCTAssertTrue(
    panel.frame.origin != before.origin,
    "the picker did not move — an anchored presentation is exactly the reported bug")
}

