// The `Theme…` command (⌘⇧K) can't anchor a popover from a menu, so it posts and this bar — which
// owns the anchor — presents. Guarded on the key window because the post reaches every window's
// accessory; toggling means the shortcut closes the dropdown as well as opening it.
.onReceive(NotificationCenter.default.publisher(for: .showThemePicker)) { _ in
  guard store.hostWindow?.isKeyWindow ?? false else { return }
  showThemePicker.toggle()
}
// "Anything else closes it." A popover dismisses itself on a click outside, but a *keyboard* command
// never sends that click — so the two things a command can do to this window close it explicitly: put
// a dialog or sheet up (a dropdown hanging over a modal is confusing and unreachable past), and move
// the selection (⌘1–9, ⌥⌘digit, the switchers), which is the action a stale dropdown would most
// obviously be sitting on top of.
.onChange(of: store.hasModalPresentation) { _, blocked in
  if blocked { showThemePicker = false }
}
.onChange(of: store.selectedTargetID) { _, _ in showThemePicker = false }

